  jQuery('#mobile-menu ul.mega-menu > li > a').addClass('mega-menu-title');

  jQuery("#mobile-menu").meanmenu({
    meanMenuContainer: ".mobile-menu",
    meanScreenWidth: "1199",
    meanExpand: ['<i class="fa fa-plus"></i>'],
  });


