//t assets/js/sidebar.js
const navSlide = () => {
  const burger = document.querySelector(".mobile-menu-btn");
  const nav = document.querySelector(".main-nav-js");
  const navLinks = document.querySelectorAll(
    ".main-nav-js .menu-list .menu-item"
  );
  const menuClose = document.querySelector(".menu-close-btn");
  if (burger) {
    burger.addEventListener("click", () => {
      nav.classList.add("show-menu");
      navLinks.forEach((link, index) => {
        if (link.style.animation) {
          link.style.animation = "";
        } else {
          link.style.animation = `navLinkFade 0.4s ease forwards ${
            index / 10 + 0.5
          }s `;
        }
      });
    });
    menuClose.addEventListener("click", () => {
      nav.classList.remove("show-menu");
      navLinks.forEach((link, index) => {
        if (link.style.animation) {
          link.style.animation = "";
        } else {
          link.style.animation = `navLinkFade 0.4s ease forwards ${
            index / 10 + 0.5
          }s `;
        }
      });
    });
  }
};
navSlide();

jQuery(".main-nav-js .bi").on("click", function (event) {
  var jQueryfl = jQuery(this);
  jQuery(this).parent().siblings().find(".sub-menu").slideUp();
  jQuery(this).parent().siblings().find(".bi").addClass("fa fa-plus");
  if (jQueryfl.hasClass("fa fa-plus")) {
    jQueryfl.removeClass("fa fa-plus").addClass("fa fa-minus");
  } else {
    jQueryfl.removeClass("fa fa-minus").addClass("fa fa-plus");
  }
  jQueryfl.next(".sub-menu").slideToggle();
});


